actions.script:
def p = ec.web.parameters
def _searchText = p.searchText; def _fromDate = p.fromDate; def _thruDate = p.thruDate
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def f = ec.entity.find("zenith.erp.pos.PosItemPriceOverrideView")
if (_org && _org != '_NA_') f.condition("organizationPartyId", _org)
if (_fromDate) f.condition("changeDate", "greater-equals", java.sql.Timestamp.valueOf(_fromDate + ' 00:00:00'))
if (_thruDate) f.condition("changeDate", "less-equals", java.sql.Timestamp.valueOf(_thruDate + ' 23:59:59'))
f.orderBy("-changeDate")
def rows = f.list()
def st = (_searchText ?: '').trim().toLowerCase()
if (st) rows = rows.findAll { r -> def nm = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString();
    [r.transactionNumber, r.productName, r.productId, r.sessionId, nm]
        .collect { (it ?: '').toString().toLowerCase() }.any { it.contains(st) } }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def dt = { v -> v == null ? "" : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
def amt = { v -> v == null ? "0.00" : ec.l10n.format((v as BigDecimal), '#,##0.00') }
def who = { r -> def nm = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString().trim(); nm ?: (r.changedByPartyId ?: '') }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Price Override Audit Log (amounts before GST)\n")
csv.append("Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Date / Time,Bill No,Product,Product ID,Original Price,New Price,Difference,Changed By,Session\n")
rows.each { r ->
    def orig = r.originalPrice != null ? (r.originalPrice as BigDecimal) : 0G
    def np = r.newPrice != null ? (r.newPrice as BigDecimal) : 0G
    def d = np - orig
    csv.append("${esc(dt(r.changeDate))},${esc(r.transactionNumber)},${esc(r.productName)},${esc(r.productId)},${esc(amt(orig))},${esc(amt(np))},${esc((d>=0G?'+':'-')+amt(d.abs()))},${esc(who(r))},${esc(r.sessionId)}\n")
}
ec.web.sendTextResponse(csv.toString(), "text/csv", "Price_Overrides_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def _org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def _uri = (ec.web?.request?.requestURI ?: '')
def _zi = _uri.indexOf('/zenith/')
appBase = _zi > 0 ? _uri.substring(0, _zi) : ''

def f = ec.entity.find('zenith.erp.pos.PosItemPriceOverrideView')
if (_org && _org != '_NA_') f.condition('organizationPartyId', _org)
if (fromDate) f.condition('changeDate', 'greater-equals', java.sql.Timestamp.valueOf(fromDate + ' 00:00:00'))
if (thruDate) f.condition('changeDate', 'less-equals', java.sql.Timestamp.valueOf(thruDate + ' 23:59:59'))
def raw = f.list()
def st = (searchText ?: '').trim().toLowerCase()
if (st) raw = raw.findAll { r -> def nm = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString();
    [r.transactionNumber, r.productName, r.productId, r.sessionId, nm]
        .collect { (it ?: '').toString().toLowerCase() }.any { it.contains(st) } }

def fmt2 = { v -> ec.l10n.format((v ?: 0G) as BigDecimal, '#,##0.00') }
def all = raw.collect { r ->
    def orig = r.originalPrice != null ? (r.originalPrice as BigDecimal) : 0G
    def np = r.newPrice != null ? (r.newPrice as BigDecimal) : 0G
    def d = np - orig
    def who = "${r.firstName ?: ''} ${r.lastName ?: ''}".toString().trim()
    [changeDate: r.changeDate, bill: (r.transactionNumber ?: ''), product: (r.productName ?: ''),
     productId: (r.productId ?: ''), orig: orig, np: np, diff: d, who: (who ?: (r.changedByPartyId ?: '')), session: (r.sessionId ?: ''),
     dateStr: (r.changeDate != null ? ec.l10n.format(r.changeDate, 'dd MMM yyyy hh:mm a') : ''),
     origStr: '₹' + fmt2(orig), newStr: '₹' + fmt2(np),
     diffStr: (d > 0G ? '+' : (d < 0G ? '-' : '')) + '₹' + fmt2(d.abs()),
     diffClass: (d < 0G ? 'success' : (d > 0G ? 'danger' : 'grey'))]
}

// sort by orderByField (whitelist; leading '-' = desc)
def curOb = orderByField ?: '-changeDate'
def desc = curOb.startsWith('-'); def key = desc ? curOb.substring(1) : curOb
def keyMap = [changeDate:'changeDate', transactionNumber:'bill', productName:'product', productId:'productId',
              originalPrice:'orig', newPrice:'np', priceDiff:'diff', changedBy:'who', sessionId:'session']
def sk = keyMap[key] ?: 'changeDate'
all = all.sort { a, b -> def av = a[sk]; def bv = b[sk];
    (av instanceof Comparable && bv != null && av.class == bv.class) ? (av <=> bv) : ((av ?: '').toString().toLowerCase() <=> (bv ?: '').toString().toLowerCase()) }
if (desc) all = all.reverse()
sortCols = [:]
['changeDate','transactionNumber','productName','productId','originalPrice','newPrice','priceDiff','changedBy','sessionId'].each { fld ->
    def a = (curOb == fld); def dn = (curOb == '-' + fld)
    sortCols[fld] = [next: (a ? '-' + fld : fld), arrow: (a ? ' ▲' : (dn ? ' ▼' : ''))]
}

// paginate (10 per page, matching the mockup)
totalCount = all.size()
def pageSize = 10
def pIdx = 0
try { if (pageIndex) pIdx = (pageIndex as Integer) } catch (Exception ig) { pIdx = 0 }
pageCount = (int) Math.ceil(totalCount / (double) pageSize); if (pageCount < 1) pageCount = 1
if (pIdx < 0) pIdx = 0; if (pIdx >= pageCount) pIdx = pageCount - 1
curPage = pIdx
def fromIx = pIdx * pageSize
def toIx = Math.min(fromIx + pageSize, totalCount)
rows = (fromIx < totalCount) ? all.subList(fromIx, toIx) : []
showFrom = totalCount == 0 ? 0 : (fromIx + 1)
showTo = toIx
def ws = Math.max(0, pIdx - 3); def we = Math.min(pageCount, ws + 7)
pageNums = (ws..<we).toList()
